import 'package:isar_community/isar.dart';

import '../../../app_config.dart';
import '../../../wallets/crypto_currency/crypto_currency.dart';

part 'contact_entry.g.dart';

@collection
class ContactEntry {
  ContactEntry({
    this.emojiChar,
    required this.name,
    required this.addresses,
    required this.isFavorite,
    required this.customId,
  });

  Id id = Isar.autoIncrement;

  late final String? emojiChar;
  late final String name;
  late final List<ContactAddressEntry> addresses;
  late final bool isFavorite;

  @Index(unique: true, replace: true)
  late final String customId;

  @ignore
  List<ContactAddressEntry> get addressesSorted {
    final List<ContactAddressEntry> sorted = [];
    for (final coin in AppConfig.coins) {
      final slice = addresses.where((e) => e.coin == coin).toList();
      if (slice.isNotEmpty) {
        slice.sort((a, b) => a.address.compareTo(b.address));
        sorted.addAll(slice);
      }
    }

    return sorted;
  }

  ContactEntry copyWith({
    bool shouldCopyEmojiWithNull = false,
    String? emojiChar,
    String? name,
    List<ContactAddressEntry>? addresses,
    bool? isFavorite,
  }) {
    final List<ContactAddressEntry> _addresses = [];
    if (addresses == null) {
      for (final e in this.addresses) {
        _addresses.add(e.copyWith());
      }
    } else {
      for (final e in addresses) {
        _addresses.add(e.copyWith());
      }
    }
    String? newEmoji;
    if (shouldCopyEmojiWithNull) {
      newEmoji = emojiChar;
    } else {
      newEmoji = emojiChar ?? this.emojiChar;
    }

    return ContactEntry(
      emojiChar: newEmoji,
      name: name ?? this.name,
      addresses: _addresses,
      isFavorite: isFavorite ?? this.isFavorite,
      customId: customId,
    );
  }

  Map<String, dynamic> toMap() {
    return {
      "emoji": emojiChar,
      "name": name,
      "addresses": addresses.map((e) => e.toMap()).toList(),
      "id": customId,
      "isFavorite": isFavorite,
    };
  }
}

@embedded
class ContactAddressEntry {
  late final String coinName;
  late final String address;

  @ignore
  CryptoCurrency get coin => AppConfig.getCryptoCurrencyFor(coinName)!;

  ContactAddressEntry();

  ContactAddressEntry copyWith({CryptoCurrency? coin, String? address}) {
    return ContactAddressEntry()
      ..coinName = coin?.identifier ?? coinName
      ..address = address ?? this.address;
  }

  Map<String, String> toMap() {
    return {"address": address, "coin": coin.identifier};
  }

  @override
  String toString() {
    return "AddressBookEntry: ${toMap()}";
  }
}
